class Solution {
public:
    string arrangeWords(string text) {
        vector<pair<int,string>> v;
        stringstream ss(text);
        string w;
        int idx = 0;
        while (ss >> w) { v.push_back({idx++, w}); }
        stable_sort(v.begin(), v.end(), [](auto& a, auto& b){
            return a.second.size() < b.second.size();
        });
        string res;
        for (int i = 0; i < (int)v.size(); ++i) {
            if (i) res += ' ';
            transform(v[i].second.begin(), v[i].second.end(), back_inserter(res), ::tolower);
        }
        res[0] = toupper(res[0]);
        return res;
    }
};

