class Solution {
    public String arrangeWords(String text) {
        String[] words = text.split(" ");
        Integer[] idx = new Integer[words.length];
        for (int i = 0; i < idx.length; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> words[a].length() != words[b].length()
                ? words[a].length() - words[b].length() : a - b);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < idx.length; i++) {
            String w = words[idx[i]].toLowerCase();
            if (i == 0) w = Character.toUpperCase(w.charAt(0)) + w.substring(1);
            sb.append(w);
            if (i < idx.length - 1) sb.append(' ');
        }
        return sb.toString();
    }
}

