var arrangeWords = function(text) {
    const words = text.split(' ').map((w, i) => [w.length, i, w.toLowerCase()]);
    words.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
    let res = words.map(x => x[2]).join(' ');
    return res[0].toUpperCase() + res.slice(1);
};

