class Solution:
    def arrangeWords(self, text: str) -> str:
        words = text.split()
        buckets = [[] for _ in range(len(text) + 1)]
        for w in words:
            buckets[len(w)].append(w.lower())
        res = ' '.join(w for b in buckets for w in b)
        return res[0].upper() + res[1:]

