class Solution {
public:
    string arrangeWords(string text) {
        vector<vector<string>> buckets(text.size() + 1);
        stringstream ss(text);
        string w;
        while (ss >> w) {
            transform(w.begin(), w.end(), w.begin(), ::tolower);
            buckets[w.size()].push_back(w);
        }
        string res;
        for (auto& b : buckets)
            for (auto& x : b) {
                if (!res.empty()) res += ' ';
                res += x;
            }
        res[0] = toupper(res[0]);
        return res;
    }
};

